.button-primary,
.button-secondary,
.add-printer,
.launch-monitor {
  display: inline-flex;
  align-items: center;
  gap: var(--button-secondary-icon-gap);
  font: var(--font-body-small);
  padding: var(--button-secondary-padding);
  border-radius: var(--radius-small);
  cursor: pointer;
}

.button-primary {
  gap: var(--button-primary-icon-gap);
  font: var(--font-body-small-bold);
  padding: var(--button-primary-padding);
  border-radius: var(--radius-medium);
  color: var(--action-primary-text);
  background: var(--action-primary);
  border: 0;
}

.button-primary:hover {
  background: var(--action-primary-hover);
}

/* Import and Launch monitor are outlined, not plain text: as text they
   stopped reading as controls. */
.button-secondary,
.launch-monitor {
  color: var(--text-primary);
  background: transparent;
  border: 1px solid var(--border-subtle);
}

.button-secondary:hover,
.launch-monitor:hover {
  background: var(--surface-subtle);
}

/* New beside Open…: the design system's compact outlined button, 28 px. */
.button-secondary-small {
  padding: var(--button-secondary-small-padding);
  height: var(--button-secondary-small-height);
}

