TEST_CASE("button recipes name a type role instead of a raw size", "[brand]")
{
    const json tokens = load_tokens();
    std::set<std::string> roles;
    for (const auto& [role, spec] : tokens.at("typography").at("roles").items())
        roles.insert(role);
    for (const auto& [name, recipe] : tokens.at("component").at("button").items()) {
        INFO("component.button." << name);
        CHECK_FALSE(recipe.contains("textSize"));
        if (recipe.contains("textRole")) {
            INFO("component.button." << name << ".textRole = " << recipe.at("textRole"));
            REQUIRE(recipe.at("textRole").is_string());
            CHECK(roles.count(recipe.at("textRole").get<std::string>()) == 1);
        }
    }
}
---
    CHECK(theme.palette(false).axis_x == wxColour(0xFF, 0x3C, 0x5B));
    CHECK(theme.palette(false).axis_y == wxColour(0x64, 0xC8, 0x18));
    CHECK(theme.palette(false).axis_z == wxColour(0x2F, 0x88, 0xE9));
    CHECK(theme.palette(true).axis_x == theme.palette(false).axis_x);
    CHECK(theme.palette(true).axis_z == theme.palette(false).axis_z);

    CHECK(m.button.icon.width == 32);
    CHECK(m.button.icon.icon_size == 16);
    CHECK(m.button.icon_compact.width == 26);
    CHECK(m.button.icon_compact.height == 26);
    CHECK(m.button.icon_compact.icon_size == 16);
    CHECK_FALSE(m.button.icon.text_role.has_value());
    CHECK(m.button.window.text_role == TextRole::Label);
    CHECK(m.button.compact.text_role == TextRole::Metadata);
    CHECK(m.button.expanded.min_height == 32);
    CHECK(m.button.primary.padding_y == 8);
    CHECK(m.button.primary.radius == 8);
    CHECK(m.button.primary.text_role == TextRole::BodySmallBold);
    CHECK(m.printer_card.column_width == 320);
    CHECK(m.printer_card.radius == 12);
}

