/* Buttons */
.jp-btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; box-sizing: border-box; margin: 0; border: 0; white-space: nowrap; cursor: pointer; }
.jp-btn:disabled { cursor: default; }
.jp-btn:focus-visible, .jp-seg-item:focus-visible, .jp-swatch:focus-visible, .jp-chat-header-btn:focus-visible, .jp-chat-header-back:focus-visible { outline: 2px solid var(--border-focus); outline-offset: 2px; }
.jp-btn-glyph { display: inline-flex; flex: none; }

.jp-btn-primary { padding: var(--space-8) var(--space-16); border-radius: var(--radius-medium); background: var(--action-primary); color: var(--action-on-primary); }
.jp-btn-primary:hover:enabled { background: var(--action-primary-hover); }
.jp-btn-primary:active:enabled { background: var(--action-primary-pressed); }
.jp-btn-primary:disabled { opacity: 0.4; }

.jp-btn-secondary { padding: 6px var(--space-12); border-radius: var(--radius-small); background: transparent; color: var(--text-primary); box-shadow: inset 0 0 0 1px var(--border-subtle); }
.jp-btn-secondary:hover:enabled { background: var(--surface-subtle); }
.jp-btn-secondary:active:enabled { background: var(--surface-selected); }
.jp-btn-secondary:disabled { color: var(--text-secondary); opacity: 0.5; }

.jp-btn-danger { padding: 6px var(--space-12); border-radius: var(--radius-small); background: transparent; color: var(--status-danger); box-shadow: inset 0 0 0 1px var(--status-danger); }
.jp-btn-danger:hover:enabled { background: var(--surface-subtle); }
.jp-btn-danger:active:enabled { background: var(--surface-selected); }
.jp-btn-danger:disabled { background: var(--action-disabled); color: var(--action-disabled-text); box-shadow: none; }

.jp-btn-icon { width: 32px; height: 32px; padding: 0; border-radius: var(--radius-small); background: transparent; color: var(--text-secondary); }
.jp-btn-icon:hover:enabled { background: var(--surface-subtle); }
.jp-btn-icon:active:enabled { background: var(--surface-selected); }
.jp-btn-icon:disabled { opacity: 0.4; }
.jp-btn-icon-compact { width: 26px; height: 26px; color: var(--text-primary); }

.jp-btn-compact.jp-btn-primary { padding: var(--space-4) var(--space-16); }
.jp-btn-compact.jp-btn-secondary { padding: var(--space-4) var(--space-12); }
.jp-btn-block { display: flex; width: 100%; }

49:.jp-split { display: inline-flex; height: 34px; border-radius: var(--radius-medium); }
